from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe')
expected='227b00fb0142aa92df0c826f27980b65e2a452ad'
def git(*a):return subprocess.run(['git',*a],cwd=repo,check=True,text=True,capture_output=True).stdout
if git('rev-parse','HEAD').strip()!=expected or git('rev-parse','origin/main').strip()!=expected:raise SystemExit('HEAD_CHANGED')
entries=[i for i in git('status','--porcelain=v1','-z').split('\0') if i]
print('STATUS',repr(entries))
allow={'adapters/protocol.py','do-again.toml','do-again-policy.json','jobctl.py','tests/test_jobctl.py','tests/test_ats_adapter_contract.py'}
if any(i[3:] not in allow for i in entries):raise SystemExit('UNEXPECTED_DIRTY')
for name,required in [('jobctl.py','getattr(item, "row", {})'),('tests/test_jobctl.py','test_apply_csv_explicit_uncertain_status_never_initializes_ats'),('tests/test_ats_adapter_contract.py','page.set_default_timeout(10_000)')]:
 if required not in (repo/name).read_text():raise SystemExit('EXPECTED_PATCH_MISSING '+name)
def test(args,timeout):
 p=subprocess.Popen([str(repo/'.venv/bin/python'),'-m','pytest','-q','--maxfail=1']+args,cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try:o,e=p.communicate(timeout=timeout)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try:o,e=p.communicate(timeout=8)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate()
  print('TEST_TIMEOUT',args,o[-2200:]);raise SystemExit(124)
 print('TEST_RESULT',args,'exit',p.returncode,o[-3400:],e[-450:])
 return p.returncode
# Split by test-file group, each pytest invocation bounded; collectively exercise every test_*.py
files=sorted(x.relative_to(repo).as_posix() for x in (repo/'tests').rglob('test_*.py') if '__pycache__' not in x.parts)
if not files:raise SystemExit('NO_TESTS')
groups=[[],[],[],[]]
for i,name in enumerate(files):groups[i%4].append(name)
print('TEST_FILE_COUNT',len(files),'GROUP_SIZES',[len(g) for g in groups])
for i,group in enumerate(groups):
 if test(group,840):raise SystemExit('GROUP_FAILED_'+str(i))
print('ALL_TEST_GROUPS_PASSED')
subprocess.run(['git','add','--','jobctl.py','tests/test_jobctl.py','tests/test_ats_adapter_contract.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','fix: block uncertain registration override and stabilize ATS test timeout'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True,timeout=90)
print('VERIFIED_PUSH',git('rev-parse','HEAD').strip())
